INSERT INTO meters(org_id, facility_id, factor_key, label, unit, method) SELECT DISTINCT ON (r.facility_id, r.factor_key) r.org_id, r.facility_id, r.factor_key, f.name, r.unit, r.method FROM records r JOIN factors f ON f.key = r.factor_key ORDER BY r.facility_id, r.factor_key, r.end_date DESC ON CONFLICT DO NOTHING;
